fn should_end_object_finish_kill_priority_battle(version, rnd, player, data, main_objective) -> bool

// ── L1216 진입 게이트 ───────────────────────────────
if (main_objective_bits & 0xFFFE) != 0x0300 { return false }
//   = main_objective 가 Morgard{phase:Hunt,..} 또는 Serpen{phase:Hunt,..} 일 때만 계속.
//     byte0=tag(0=Morgard/1=Serpen), byte1=ObjectPhase(3=Hunt), byte2=with_battle 는 무시.

// ── L1220 전략 게이트 ──────────────────────────────
let st: Strategy = PlayerState::strategy(player, rnd, data.cache.game.data, data.cache.game.vtable);  // sret 24B
if st.object_finish /*+0xf*/ != ObjectFinishStrategy::KillPriority /*0*/ { return false }
//   IR 은 PartialEq::ne 가 인라인돼 `icmp eq i8 tag, 0` 로 남아 있다.

// ── L1224~1225 목표 엔티티 확보 ─────────────────────
// objective_entity_id_for_main_objective(fight_model.rs:1179~1183) 가 통째로 인라인됨
let game = data.cache.game;                     // AbstractGameWithCache +0x0(data) / +0x8(vtable)
let mode: GameMode = game.vtable[+0x40](game.data);      // {tag:i64, payload:ptr}
if mode.tag != 0 /*Moba*/ { return true }                // as_moba() == None
let m: &MobaMode = mode.payload;
let camp = if main_objective.tag == 0 { m.jungle_runner.epic   /* MobaMode+0x198 */ }   // L1181
           else                      { m.jungle_runner.serpen /* MobaMode+0x1c8 */ };  // L1183
if camp.live_list.len == 0 { return true }               // .get(0) == None → and_then 이 None
let id: usize = camp.live_list[0];                       // .get(0).copied()
let objective: Option<&Entity> = game.vtable[+0x1f0](game.data, id);   // L1225 클로저
if objective.is_none() { return true }

// ── L1229~1230 적 챔피언 5칸 순회 (any) ──────────────
let et = 1 - player.info.team;                  // PlayerState +0x930
if et >= 2 { panic_bounds_check(et, 2) }        // iter_champions(team) 의 배열 경계검사
let row = &data.cache.player_champion[et];      // AbstractGameWithCache +0x1e0, 행 stride 40
// LLVM 이 5칸을 완전히 언롤함(슬롯 오프셋 +0,+8,+16,+24,+32)
for slot in 0..5 {
    let enemy: Option<&Entity> = row[slot];
    let Some(enemy) = enemy else { continue };                       // filter_map (None 스킵)
    // L1231
    if !Blackboard::is_recent_visible(&data.blackboard[et], game.data, game.vtable, player, enemy) { continue }
    // L1232 — fight_model::is_ignored_well_enemy(version, player, enemy) 가 인라인됨
    //   L755: enemy.team(+0x0 tag==0 && +0x8 payload==et)  == TeamType::Player(et)
    //   L756: path_finder::is_enemy_well_danger(version, player, enemy.x /*+0x660*/, enemy.y /*+0x668*/)
    if enemy.team == TeamType::Player(et)
       && is_enemy_well_danger(version, player, enemy.x, enemy.y) { continue }
    // L1233
    if can_enemy_hit_objective(enemy, objective, 25000) { return false }   // any() == true
}
// L1235
return true      // 아무 적도 목표를 때릴 수 없다 → 전투 종료

// ── 반환값 정리(IR %170 phi) ────────────────────────
// false : 진입 게이트 실패(%5) / object_finish != KillPriority(%10) /
//         적 하나라도 can_enemy_hit_objective == true (%81,%102,%123,%144,%165)
// true  : 게임모드가 Moba 아님(%27,%28) / live_list 비었음(%29,%37) /
//         엔티티 조회 실패(%45) / 5칸 다 돌았는데 아무도 못 때림(%167)
